const myObj = {
  a: 1,
  b: { c: 2, d: { e: "matching_string" } },
  f: [3, { g: 4, h: { i: "another_string", j: { k: "matching_string" } } }],
};

console.log(findEntriesByKey(myObj, "matching_string"));
// Output: [ ["b.d.e", "matching_string"], ["f[1].h.j.k", "matching_string"] ]
```

