```javascript
// Define an array of words
const words = ['skyscraper', 'chair', 'umbrella', 'curtain'];
// Create an empty array to store the objects
const wordObjects = [];
// Iterate through each word and push the corresponding object to the array
words.forEach(word => {
  const length = word.length;
  wordObjects.push({word, length});
});
// Sort the array based on the length property in ascending order
wordObjects.sort((a, b) => a.length - b.length);
// Output the sorted array as JSON
console.log(JSON.stringify(wordObjects));
```
