if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Define the specific product and time frame for loyalty identification
$product = "latte"; // replace with the name of the specific product
$week_start = date('Y-m-d', strtotime('last monday'));
$week_end = date('Y-m-d', strtotime('last sunday'));

// Execute the SQL query to identify loyal customers
$sql = "SELECT customers.name, COUNT(*) as purchase_count 
        FROM transactions 
        JOIN products ON transactions.product_id = products.id 
        WHERE products.name = '$product' 
        AND transactions.transaction_date BETWEEN '$week_start' AND '$week_end' 
        GROUP BY transactions.customer_id 
        HAVING purchase_count >= 3";

// Execute the query and store the result
$result = $conn->query($sql);

// Display the results in a table format
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Number of Purchases</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"] . "</td><td>" . $row["purchase_count"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No loyal customers found.";
}

// Close the database connection
$conn->close();
?>
```

