 Here's a simple decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and returns `next()` if it's set to "true" or `false` otherwise:

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { NextFunction } from 'express';

export const CheckNodeEnv = () => {
  return (target: Object, key: string, desc: PropertyDescriptor) => {
    const originalFn = desc.value;

    desc.value = async function (...args: any[]) {
      const context: ExecutionContext = args[2];
      const request = context.switchToHttp().getRequest();

      if (process.env.NODE_ENV === 'true') {
        await originalFn.apply(this, args);
        const next: NextFunction = args[args.length - 1];
        next();
      } else {
        return false;
      }
    };
  };
};

export const CheckNodeEnvParam = createParamDecorator((data: unknown, ctx: ExecutionContext) => {
  const request = ctx.switchToHttp().getRequest();
  return request.nodeEnv;
});
```

This decorator uses `@nestjs/common`'s `createParamDecorator` to accept an optional `nodeEnv` parameter in the middleware function. If the `NODE_ENV` environment variable is set to "true", the middleware function will call the original function with the provided arguments and then call `next()`. If not, it will return `false`.

