 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom ToastContext provider and a ToastProvider component.

1. Create a new file named `ToastContext.js`:

```javascript
import { createContext } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = React.useState([]);

  const addToast = (message, type = 'info') => {
    setToasts([...toasts, { message, type }]);
    setTimeout(() => {
      setToasts(toasts.filter((t) => t !== { message, type }));
    }, 3000);
  };

  return (
    <ToastContext.Provider value={{ addToast }}>{children}</ToastContext.Provider>
  );
};
```

2. Import and use the ToastProvider in your main App component or any other parent component:

```javascript
import React from 'react';
import { StrictMode, Suspense } from 'react';
import { ToastProvider } from './ToastContext'; // Import the ToastProvider

function App() {
  return (
    <ToastProvider>
      <StrictMode>
        <Suspense fallback={<div>Loading...</div>}>YourComponent</Suspense>
      </StrictMode>
    </ToastProvider>
  );
}

export default App;
```

