  });
}

II. Using HTMLMediaElement and getUserMedia API:

// Open Camera and Microphone
function openCameraAndMicrophone() {
  const videoElement = document.createElement("video");
  navigator.mediaDevices.getUserMedia({ video: true, audio: true }).then((stream) => {
    videoElement.srcObject = stream;
    videoElement.play();
  });
}

// Close Camera and Microphone
function closeCameraAndMicrophone() {
  const videoElement = document.querySelector("video");
  const stream = videoElement.srcObject;
  stream.getTracks().forEach((track) => {
    if (track.readyState === "live") track.stop();
  });
}

III. Using getUserMedia with Promise Chain:

// Open Camera and Microphone
function openCameraAndMicrophone() {
  return new Promise((resolve, reject) => {
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then((stream) => {
        resolve(stream);
      })
      .catch((error) => {
        reject(error);
      });
  });
}

// Close Camera and Microphone
async function closeCameraAndMicrophone(stream) {
  return new Promise((resolve) => {
    stream.getTracks().forEach((track) => {
      if (track.readyState === "live") track.stop();
    });
    resolve();
  });
}

