 To create a React utility for removing widows, you can write a custom Hook called `useNoWidows`. This Hook will be used to adjust the last line of a paragraph to prevent a single word or short phrase from appearing alone on a new line, which is commonly referred to as a widow.

Here's how you can implement it:

```jsx
import { useEffect } from 'react';

const WIDOWS_THRESHOLD = 3; // Number of characters below the line that should not be split

function isLastLineFull(text, lineHeight, fontSize) {
  const lines = text.split('\n');
  return lines[lines.length - 1].length >= (lineHeight / fontSize) * WIDOWS_THRESHOLD;
}

function getAdjustedText(text, lineHeight, fontSize) {
  if (!isLastLineFull(text, lineHeight, fontSize)) {
    return text;
  }

  const words = text.split(' ');
  let lastWordIndex = words.length - 1;

  while (lastWordIndex > 0 && words[lastWordIndex].length < WIDOWS_THRESHOLD) {
    lastWordIndex--;
  }

  if (lastWordIndex === 0) {
    return text;
  }

  const adjustedText = text.slice(0, lastWordIndex + 1) + '\n' + text.slice(lastWordIndex + 1);
  return adjustedText;
}

export function useNoWidows({ text, lineHeight, fontSize }) {
  useEffect(() => {
    const adjustedText = getAdjustedText(text, lineHeight, fontSize);
