 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Split the given sentence into words.
3. Iterate through each word in the sentence.
4. Check if the current word is in the slice of negative words or if the word before it is "not" and the next word is a negative word.
5. If either condition is true, increment a counter for double negatives.
6. After iterating through all the words, check if the counter is greater than zero.
7. If the counter is greater than zero, print a message indicating that the sentence contains a double negative.

Here's an example implementation of the above steps in Go:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "doesn't", "don't", "isn't", "aren't", "haven't", "hasn't", "hadn't", "won't", "wouldn't"}
	sentence := "He isn't not worried about the coronavirus situation"
	counter := 0

	words := strings.Split(sentence, " ")

	for i := 0; i < len(words)-1; i++ {
		if contains(negativeWords, words[i]) {
			counter++
		}
		if words[i] == "not" && contains(negativeWords, words[i+1]) {
			counter++
			break
		}
	}

	if counter > 0 {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func contains(slice []string, item string) bool {
	for _, a := range slice {
		if a == item {
			return true
		}
	}
	return false
}
```

