  const updatedRegistrations = [...this.state.registrations]; // create a copy of the current registrations array
  fetch(api.checkPortInStatus(user.getProductCode(), mnpPhoneNo), {
    headers: headers,
    method: 'GET',
  })
    .then(r => r.json())
    .then(rjson => {
